-- Core hotel-scoped triggers (M8 Phase-1; rewired to locked derivation).
DROP TRIGGER IF EXISTS trg_folio_hotel ON "Folio";
CREATE OR REPLACE FUNCTION public.trg_folio_hotel() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_hotel_id text;
BEGIN
  SELECT "Booking"."hotelId" INTO v_hotel_id
  FROM "Booking"
  WHERE "Booking"."id" = NEW."bookingId"
   ORDER BY "Booking"."id"
   FOR NO KEY UPDATE OF "Booking" SKIP LOCKED;
  IF v_hotel_id IS NULL THEN
    RAISE EXCEPTION 'cannot derive hotelId for Folio: parent row missing' USING ERRCODE = 'P0001';
  END IF;
  NEW."hotelId" := v_hotel_id;
  RETURN NEW;
END;
$$;
CREATE TRIGGER trg_folio_hotel BEFORE INSERT OR UPDATE ON "Folio" FOR EACH ROW EXECUTE FUNCTION public.trg_folio_hotel();
