DROP TRIGGER IF EXISTS trg_room_charge_hotel ON "RoomCharge";
CREATE OR REPLACE FUNCTION public.trg_room_charge_hotel() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_hotel_id text;
BEGIN
  SELECT b."hotelId" INTO v_hotel_id
  FROM br "BookingRoom"
  JOIN b "Booking" ON b."id" = br."bookingId"
  WHERE br."id" = NEW."bookingRoomId"
   ORDER BY br."id", b."id"
   FOR NO KEY UPDATE OF br, b SKIP LOCKED;
  IF v_hotel_id IS NULL THEN
    RAISE EXCEPTION 'cannot derive hotelId for RoomCharge: parent row missing' USING ERRCODE = 'P0001';
  END IF;
  NEW."hotelId" := v_hotel_id;
  RETURN NEW;
END;
$$;
CREATE TRIGGER trg_room_charge_hotel BEFORE INSERT OR UPDATE ON "RoomCharge" FOR EACH ROW EXECUTE FUNCTION public.trg_room_charge_hotel();
