-- Invoice
DROP TRIGGER IF EXISTS trg_invoice_hotel ON "Invoice";
CREATE OR REPLACE FUNCTION public.trg_invoice_hotel() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  v_hotel_id text;
BEGIN
  SELECT "Folio"."hotelId" INTO v_hotel_id
    FROM "Folio"
   WHERE "Folio"."id" = NEW."folioId"
   ORDER BY "Folio"."id"
   FOR NO KEY UPDATE OF "Folio" SKIP LOCKED;
  IF v_hotel_id IS NULL AND NEW."externalClientId" IS NOT NULL THEN
  SELECT "ExternalClient"."hotelId" INTO v_hotel_id
    FROM "ExternalClient"
   WHERE "ExternalClient"."id" = NEW."externalClientId"
   ORDER BY "ExternalClient"."id"
   FOR NO KEY UPDATE OF "ExternalClient" SKIP LOCKED;
  END IF;
  IF v_hotel_id IS NULL THEN
    RAISE EXCEPTION 'cannot derive hotelId for Invoice: parent row missing' USING ERRCODE = 'P0001';
  END IF;
  NEW."hotelId" := v_hotel_id;
  RETURN NEW;
END;
$$;
CREATE TRIGGER trg_invoice_hotel BEFORE INSERT OR UPDATE OF "folioId", "externalClientId" ON "Invoice" FOR EACH ROW EXECUTE FUNCTION public.trg_invoice_hotel();
